/**
 * Swift Woo - Main JS
 * - Live AJAX Search (nonce-verified)
 * - Slide-out Mini Cart toggle
 * - Buy Now / Order Now AJAX button
 * - Mobile Menu toggle
 * - Anti-double-submit (isSubmitting guard)
 * - BFcache reset on pageshow
 * Zero eval(), exec(), obfuscated code — scanner-safe
 * @version 1.0.0
 */
( function () {
	'use strict';

	const cfg = window.swiftWoo || {};

	/* ------------------------------------------------------------------
	 * 1. Mobile Menu Toggle
	 * ------------------------------------------------------------------ */
	const menuToggle = document.querySelector( '.swift-menu-toggle' );
	const primaryNav = document.getElementById( 'swift-primary-nav' );

	if ( menuToggle && primaryNav ) {
		menuToggle.addEventListener( 'click', function () {
			const isOpen = primaryNav.classList.toggle( 'is-open' );
			menuToggle.setAttribute( 'aria-expanded', isOpen ? 'true' : 'false' );
		} );
	}

	/* ------------------------------------------------------------------
	 * 2. Live AJAX Search
	 * ------------------------------------------------------------------ */
	const searchInput   = document.querySelector( '.swift-search-input' );
	const searchResults = document.querySelector( '.swift-search-results' );
	let searchTimer;

	if ( searchInput && searchResults && cfg.ajaxUrl && cfg.nonce ) {
		searchInput.addEventListener( 'input', function () {
			clearTimeout( searchTimer );
			const term = searchInput.value.trim();

			if ( term.length < 2 ) {
				searchResults.innerHTML = '';
				searchResults.hidden = true;
				return;
			}

			searchTimer = setTimeout( function () {
				const url = cfg.ajaxUrl
					+ '?action=swift_woo_search'
					+ '&nonce=' + encodeURIComponent( cfg.nonce )
					+ '&term=' + encodeURIComponent( term );

				fetch( url, { credentials: 'same-origin' } )
					.then( function ( r ) { return r.json(); } )
					.then( function ( data ) {
						if ( ! data.success || ! data.data.length ) {
							searchResults.innerHTML = '<p class="swift-search-no-results">কোনো পণ্য পাওয়া যায়নি।</p>';
							searchResults.hidden = false;
							return;
						}
						const html = data.data.map( function ( p ) {
							return '<a href="' + p.url + '" class="swift-search-result-item">'
								+ ( p.img ? '<img src="' + p.img + '" alt="' + p.title + '" width="48" height="48" loading="lazy">' : '' )
								+ '<span class="swift-search-result-title">' + p.title + '</span>'
								+ '<span class="swift-search-result-price">' + p.price + '</span>'
								+ '</a>';
						} ).join( '' );
						searchResults.innerHTML = html;
						searchResults.hidden = false;
					} )
					.catch( function () {
						searchResults.innerHTML = '';
						searchResults.hidden = true;
					} );
			}, 350 );
		} );

		// Close search results on outside click
		document.addEventListener( 'click', function ( e ) {
			if ( ! e.target.closest( '.swift-header__search' ) ) {
				searchResults.innerHTML = '';
				searchResults.hidden = true;
			}
		} );
	}

	/* ------------------------------------------------------------------
	 * 3. Buy Now / Order Now Button (AJAX)
	 * ------------------------------------------------------------------ */
	document.addEventListener( 'click', function ( e ) {
		const btn = e.target.closest( '.swift-buy-now-btn' );
		if ( ! btn || btn.disabled ) return;

		e.preventDefault();
		const productId = btn.dataset.productId;
		if ( ! productId ) return;

		// Anti-double-submit guard
		btn.disabled = true;
		btn.classList.add( 'is-loading' );
		const originalText = btn.textContent;
		btn.textContent = '...';

		// Collect variation data from form
		const form = btn.closest( 'form.variations_form, form.cart' );
		const formData = new FormData();
		formData.append( 'action', 'swift_woo_buy_now' );
		formData.append( 'nonce', cfg.nonce || '' );
		formData.append( 'product_id', productId );
		formData.append( 'quantity', '1' );

		if ( form ) {
			const variationId = form.querySelector( '[name="variation_id"]' );
			if ( variationId ) formData.append( 'variation_id', variationId.value );

			const selects = form.querySelectorAll( 'select[name^="attribute_"]' );
			selects.forEach( function ( s ) {
				formData.append( 'variation[' + s.name + ']', s.value );
			} );

			// Extra color hidden inputs
			const colorInputs = form.querySelectorAll( 'input[name^="swift_colors"]' );
			colorInputs.forEach( function ( inp ) {
				formData.append( inp.name, inp.value );
			} );
		}

		fetch( cfg.ajaxUrl, {
			method: 'POST',
			credentials: 'same-origin',
			body: formData,
		} )
			.then( function ( r ) { return r.json(); } )
			.then( function ( data ) {
				if ( data.success && data.data.redirect ) {
					window.location.href = data.data.redirect;
				} else {
					btn.disabled = false;
					btn.classList.remove( 'is-loading' );
					btn.textContent = originalText;
					if ( data.data && data.data.message ) {
						alert( data.data.message );
					}
				}
			} )
			.catch( function () {
				btn.disabled = false;
				btn.classList.remove( 'is-loading' );
				btn.textContent = originalText;
			} );
	} );

	/* ------------------------------------------------------------------
	 * 4. Checkout: Anti-Double-Submit
	 *    Does NOT interfere with WooCommerce's native wc_checkout_form AJAX
	 * ------------------------------------------------------------------ */
	const checkoutForm = document.querySelector( 'form.checkout' );
	if ( checkoutForm ) {
		let isSubmitting = false;
		checkoutForm.addEventListener( 'submit', function () {
			if ( isSubmitting ) return false;
			isSubmitting = true;
			setTimeout( function () { isSubmitting = false; }, 8000 );
		} );
	}

	/* ------------------------------------------------------------------
	 * 5. BFcache Fix
	 * ------------------------------------------------------------------ */
	window.addEventListener( 'pageshow', function ( e ) {
		if ( e.persisted ) {
			document.querySelectorAll( '.swift-buy-now-btn' ).forEach( function ( b ) {
				b.disabled = false;
				b.classList.remove( 'is-loading' );
			} );
		}
	} );

} )();
